# make-golden.ps1 -- regenerate the golden baseline of the normal audit report.
# Golden = full report minus the "_generated by ... on <timestamp>_" line (time varies per run).
# Why a separate script: Task-05's regression test must use the exact same filter as this capture,
# so the filter spec lives here once instead of being duplicated in the test.
$ErrorActionPreference = 'Stop'
$tools = Split-Path -Parent $PSScriptRoot
$audit = Join-Path $tools 'skill-audit.ps1'
powershell -NoProfile -ExecutionPolicy Bypass -File $audit | Out-Null
if ($LASTEXITCODE -ne 0) { throw "baseline audit not CLEAN (exit=$LASTEXITCODE)" }
$report = Join-Path $tools 'skill-audit-report.md'
$golden = Join-Path $PSScriptRoot 'golden-normal-report.txt'
$lines = [IO.File]::ReadAllLines($report) | Where-Object { $_ -notmatch '^_generated by ' }
[IO.File]::WriteAllLines($golden, $lines, (New-Object System.Text.UTF8Encoding($true)))
Write-Output "golden written: $golden ($($lines.Count) lines)"
